def solve():
    s = input().strip()
    n = len(s)
    max_len = 0

    def is_zebra(t):
        for i in range(len(t) - 1):
            if t[i] == t[i+1]:
                return False
        return True

    def check(s):
        nonlocal max_len
        if is_zebra(s):
            max_len = max(max_len, len(s))
        for i in range(1, n):
            left = s[:i]
            right = s[i:]
            rev_left = left[::-1]
            rev_right = right[::-1]
            new_s = rev_left + rev_right
            check(new_s)

    check(s)
    print(max_len)

solve()
